SELECT cd.cd_gender, cd.cd_marital_status, SUM(ss.ss_net_profit) AS total_sales_profit, COALESCE(SUM(cr.cr_net_loss), 0) AS total_return_loss, SUM(ss.ss_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) AS net_gain, CASE WHEN SUM(ss.ss_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) > 0 THEN 'Profitable' ELSE 'Loss' END AS profit_status, RANK() OVER (ORDER BY SUM(ss.ss_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) DESC) AS profit_rank, ARRAY_AGG(DISTINCT w.w_warehouse_name) AS warehouses FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk LEFT JOIN catalog_returns cr ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cd.cd_gender, cd.cd_marital_status ORDER BY net_gain DESC LIMIT 20
